-- GENERATED by `wfj generate` from data/gossip/gossip-b7.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["b707dc8d0c84b4c2"] = { "Anima del Demone?", "." },
  ["b70afd9a6313a8a3"] = { "Hai qualche nuovo tesoro da tenere al sicuro, eh? Allora vorrai custodirlo a The Vault, dagli Stonemantle. The Vault è a un tiro di martello a nord-est dall'ingresso di ⟦Ironforge=Forgiardente⟧.", "." },
  ["b712e1d5a39343b1"] = { "<Un/Una> <altro/altra> erborista, mmh. Dubito che la tua abilità sia grande quanto la mia, quindi forse posso insegnarti qualche tecnica come si deve.", "." },
  ["b7269c59899c8231"] = { "FUOCO! MORTE! DISTRUZIONE! Tremate, mortali, davanti all'ira di lord... NO! DEVO combatterlo! Alexstrasza, aiutami, DEVO combatterlo!", "." },
  ["b728680ebbf8343e"] = { "Se mai qualcuno mi chiamerà, mortale, un sacrificio sarà dovuto...", "." },
  ["b72c70b6a9ed261c"] = { "Nero, grigio e viola scuro sono i colori prescritti. Bada a non finire dalla parte sbagliata della strada della moda, amico. Bowen Brisboise può aiutarti a evitarlo. Lo troverai dentro il ⟦Cold Hearth Manor=Maniero Cuorduro⟧, dall'altra parte del ponte a sud-ovest della città.", "." },
  ["b730647315663121"] = { "Hai intrapreso una strada onorevole, {name}. I miei antenati rispettano la tua buona volontà, ma non avrai la mia approvazione finché non avrai portato a termine i miei compiti.\n\nSai cosa devi fare se vuoi dimostrare di avere lo spirito del cacciatore.", "." },
  ["b73292015bf55580"] = { "Voglio vedere la tua merce.", "." },
  ["b7397a58a8bc35b0"] = { "La Società Reale degli Speziali ha poca pazienza con gli sciocchi, e io pure. Forse la prossima volta che parleremo dei miei destrieri sarai <Osannato/Osannata> presso ⟦Undercity=Sepulcra⟧. Fino ad allora...", "." },
  ["b73c3219eb4fac3b"] = { "Eccolo: il deserto di Tanaris. Buffo come un posto inospitale come questo sembri migliore di una giungla rigogliosa, dopo esserci rimasti intrappolati per un'eternità.", "." },
  ["b7444ff6945ff340"] = { "La Luce ha parlato!", "." },
  ["b749458cfe46bdd5"] = { "Questa vivace pianta di drago notturno spicca in netto contrasto con la corruzione demoniaca che lacera ⟦Felwood=Vilbosco⟧. Frutti rari e succosi, noti come ⟦Night Dragon's Breath=Mentina all'Alito di Drago⟧, pendono pesanti dalla pianta.", "." },
  ["b750af9637971df4"] = { "Stoltamente hai cercato la tua stessa fine.", "." },
  ["b7520c03741954df"] = { "La tua morte non sarà stata vana, Taelan. Oggi nasce un nuovo Ordine... un Ordine che si dedicherà a estinguere il male che affligge questo mondo. Un male che non può nascondersi dietro la politica e le cortesie.", "." },
  ["b758afccd844127a"] = { "Nella ⟦Alterac Valley=Valle d'Alterac⟧ infuriano le battaglie e l'equipaggiamento scarseggia.", "." },
  ["b76a1973e6feb186"] = { "Devi essere Osannato presso i troll della tribù ⟦Darkspear=Lanciascura⟧ prima che ti insegni a cavalcare, {class}.", "." },
  ["b76f90d0c51a54b6"] = { "Salute, viaggiatore. Finché resti tra le mura della ⟦Cenarion Hold=Fortezza Cenariana⟧, sarai al sicuro.\n\nFai attenzione quando lasci la protezione della Fortezza: di recente i silitidi sciamano ovunque.", "." },
  ["b7721be0640e172f"] = { "Ottimo, {name}! Troverai Brogun Stoneshield sulla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧. Può aiutarti a raggiungere la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["b7783dd179fbc2fd"] = { "Infermiera.", "." },
  ["b77f35e1b2fd2956"] = { "Ci penso io, Ich. Dammi un segnalatore!", "." },
  ["b780d0dc9601a577"] = { "È bello essere il re! Ora, torniamo a quello di cui parlavi prima...", "." },
  ["b784f2f4bdabecdc"] = { "Non c'è posto migliore per imparare il ⟦First Aid=Primo Soccorso⟧ che sotto l'occhio vigile di Shaina Fuller, alla ⟦Cathedral of Light=Cattedrale della Luce⟧.\n\nPer arrivarci, cerca i tetti gialli o l'altissima guglia della Cattedrale stessa, che si vede da quasi ogni punto della città.", "." },
  ["b7893fe49f40afbb"] = { "Vuoi dire che non lo sai? La spada che porti sulla schiena è nota come il Brandicenere, dal nome del suo primo proprietario.", "." },
  ["b7912278b19219a6"] = { "Come puoi averne la certezza? Se non abbiamo mai trattato direttamente con il signore del vento, non vale la pena tentare?", "." },
  ["b79549fec67f9808"] = { "Non ho più la mia ⟦Zandalar Demoniac's Robe=Tonaca Demoniaca degli Zandalari⟧. Puoi darmene una nuova?", "." },
  ["b79af7960d76fdce"] = { "Già, sei proprio un genio. Quanto ti credi intelligente, Slip'kik?", "." },
  ["b7a3793ac3b44a79"] = { "Cosa cerchi, {class}?", "." },
  ["b7a39a327223751e"] = { "Davvero, ti invidio: combattere in nome dell'⟦Horde=Orda⟧, in prima linea. Il mio è un compito di comando.\n\nCerto, in gioventù ho vissuto i sogni che rendono sopportabile la mia vecchiaia. Ora mi godo la gloria della vittoria e il sapore amaro della sconfitta, tutto attraverso i soldati che comando.", "." },
  ["b7a6ebd0dd7b04c0"] = { "Allora cerca Dawnstrider Enchanters sull'altura di mezzo. Teg sarà ben felice di aiutarti come può.", "." },
  ["b7b1c6847b1b581c"] = { "Te la cavi davvero bene con gli incantamenti! Ora è tempo che tu vada avanti. Voglio che parli con Gimble Thistlefuzz, al piano di sopra. È un tipo un po' strano, ma d'ora in poi ti indicherà la strada giusta!", "." },
  ["b7b1d4ae206b25a0"] = { "Subito, servitore.", "." },
  ["b7b62b109b2ffe06"] = { "Spero che tu stia bene, considerato tutto.\n\nSiediti un momento e ascolta la mia storia. È una tragedia, naturalmente, ma spero che finisca con una vendetta!", "." },
  ["b7bde49246db66e0"] = { "Non tutto è perduto! Combattete queste bestie senza paura. Curerò le vostre ferite, risanerò le vostre ossa. Siate rinnovati, eroi!", "." },
  ["b7cc4bb3c650106e"] = { "Ci vuole ben più di voi, marmaglia, per buttarmi giù!", "." },
  ["b7ce4a42cd4bef5c"] = { "Me ancora capo di ogre. Ah ah!", "." },
  ["b7d272eeccdcd3f8"] = { "Ehi, Jangdor, puoi insegnarmi di nuovo a fare le ⟦Wild Leather Leggings=Gambiere di Cuoio Selvatico⟧?", "." },
  ["b7d7a076a0308802"] = { "Mi servirà un po' d'aiuto con questo, {name}!", "." },
  ["b7e2465f7cd2f0a4"] = { "Se ti manda Therzok, digli di no: non tornerò a lavorare per lui, non importa quante volte me lo chieda.", "." },
  ["b7e35903aba8f524"] = { "Forte nel corpo e nello spirito. Non può esserci combinazione più forte! Trova il tuo destino con Sark Ragetotem nella Hunter's Hall.", "." },
  ["b7ee32bb93e247e6"] = { "Studiare e comprendere il Colosso ci darà il vantaggio di cui abbiamo bisogno sui Qiraji.", "." },
  ["b7fcdec6b7db1938"] = { "Il ⟦Frostwolf Graveyard=Cimitero dei Lupi Bianchi⟧ è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["b7ff2d79351b6cff"] = { "Va' alla Cleft of Shadow e cerca Spellweaver Mon'ye, vicino al centro del quartiere.", "." },
})
